{
  "agreement": {
    "effectiveDate": "______ 20____ (the \"Effective Date\")",
    "parties": [
      {
        "name": "Chubb Limited",
        "registeredOffice": "Zurich, Switzerland",
        "role": "company"
      },
      {
        "name": "Indemnitee",
        "role": "director and/or officer of the company"
      }
    ],
    "purpose": "amend and restate the company’s indemnification arrangement to provide fullest lawful protection and expense advances for the Indemnitee, including covering obligations under stock‑exchange rules and any future amendments that broaden indemnification rights.",
    "definitions": {
      "Board": "Board of Directors of the Company",
      "Affiliate": "any entity directly or indirectly controlling or controlled by or under common control with the specified person",
      "ChangeInControl": {
        "triggers": [
          "50%+ voting stock owned by a new person (excluding acquisition by company/subsidiary, employee benefit plan, or temporary underwriter holdings)",
          "majority of Board consists of non‑incumbent directors (incumbent defined as Board on Effective Date; new directors backed by 75% of incumbents considered incumbent)",
          "shareholder approval of liquidation plan distributing all/substantially all assets",
          "disposal of all/substantially all assets/business through merger, consolidation, or other transaction, unless prior shareholders own substantially same proportion in successor",
          "combination with another company where surviving corporation is the Company but prior shareholders hold ≤50% of voting stock of the combined entity (excluding shares received by affiliates in exchange for issues)"
        ],
        "definitions": {
          "Affiliate": "as above",
          "VotingStock": "capital stock with voting power to elect directors"
        }
      },
      "Expenses": "All costs related to defending, prosecuting, or participating in a Proceeding tied to an Indemnifiable Event (including attorneys’ fees, judgments, fines, filings, travel, ERISA taxes, settlements, interest, appeals bonds, etc.)",
      "IndemnifiableEvent": "Any event/occurrence before or after this Agreement linked to Indemnitee’s role (direct, officer, employee, trustee, agent, fiduciary) in the Company or a related entity, whether in official capacity or otherwise.",
      "IndependentCounsel": "person/body appointed per Section 3 for post‑Change‑in‑Control matters",
      "Proceeding": "any threatened, pending, or completed civil, criminal, administrative, investigative, or alternative dispute resolution action/claim involving Indemnitee",
      "ReviewingParty": {
        "pre‑ChangeInControl": "Board member(s) or other non‑party to the proceeding",
        "post‑ChangeInControl": "Independent Counsel"
      },
      "VotingSecurities": "securities that vote generally in director elections"
    },
    "clause1": {
      "generalIndemnification": "Company shall indemnify Indemnitee from all Expenses to the fullest extent permitted by law and applicable stock‑exchange regulation, exceeding any limitation strictly prescribed by the Articles, shareholders, or other law."
    },
    "clause2": {
      "initiatingProceeding": "Indemnitee is not entitled to indemnification for a proceeding brought by Indemnitee against the company unless: (i) Company/Board consents, (ii) It enforces indemnification rights under Section 5, or (iii) It is a post‑Change‑in‑Control proceeding with Independent Counsel approval."
    },
    "clause3": {
      "expenseAdvances": "Upon request, Company shall advance Expenses within ten business days if Indemnitee provides a repayment undertaking. If Indemnitee proves entitled to indemnity, no reimbursement required. If vindicated, reimbursement is unpaid until final judicial resolution. Beckoning cost: unsecured, no interest. Advance requires itemized statement, engagement letter, and other reasonable info."
    },
    "clause4": {
      "mandatoryIndemnification": "Indemnitee gets indemnification for all Expenses when successfully defending a proceeding or any part thereof.",
      "partialIndemnification": "Indemnify the portion of Expenses to which Indemnitee is entitled.",
      "prohibitedIndemnification": "No indemnity for: (i) accounting judgments for profits from company securities per S.E.A. §16(b), (ii) fiduciary breach where Willful or Gross negligence per court, (iii) court decision that indemnity prohibited, (iv) settlement where Indemnitee acted in bad faith, willfully or fraudulently."
    },
    "clause5": {
      "reviewingPartyProcedure": "Pre‑Change‑in‑Control: Board/non‑party; Post‑Change‑in‑Control: Independent Counsel. Independent Counsel chosen by Indemnitee, approved by Company, must not have served either party in last five years. Counsel gives written opinion; Company pays reasonable fees; Indemnitee must cooperate; any Cost of cooperation paid by Company."
    },
    "clause6": {
      "indemnificationProcess": "Indemnitee may demand indemnification; Company pays promptly unless Reviewing Party dismisses claim. Indemnitee may sue in SDNY within 30 days of demand if indemnity not paid. Defenses by Company: burden on Company, presumptively indemnifiable if Indemnitee demands. Final judgement does not create presumption of lack of conduct."
    },
    "clause7": {
      "expensesInEnforcement": "Company indemnifies Indemnitee for out‑of‑pocket costs in action to enforce indemnification or recover insurance, but only if Indemnitee ultimately entitled. Advance those costs per Section 3."
    },
    "clause8": {
      "noticeAndDefense": "Indemnitee must promptly notify Company of proceeding commencement. Company may participate at own expense, may assume defense with counsel acceptable to Indemnitee. If Company assumes defense, Indemnitee bears Expenses except reasonable investigation costs or as specified. Indemnitee may retain counsel if conflict, post‑Change‑in‑Control or Independent Counsel approves. Settlement costs paid without Company consent are not indemnified unless Independent Counsel approves post‑Change‑in‑Control.",
      "settlement": "Company liable for settlements only if Independent Counsel approves. Company must avoid imposing penalty or limitation on Indemnitee without written consent."
    },
    "clause9": {
      "trustOrEscrow": "Upon Change‑in‑Control (unless approved majority of pre‑change Board): Company creates trust/escrow at Indemnitee request. Amount funded per Independent Counsel. Trustee/escrow agent advanc ees within ten business days. Unused funds return to Company upon final determination. Income is tax‑reported by Company."
    },
    "clause10": {
      "nonExclusivity": "Indemnification rights here are in addition to all rights under Articles or law and supersede prior indemnification agreements."
    },
    "clause11": {
      "liabilityInsurance": "If Company maintains directors’ and officers’ liability insurance, Indemnitee covered to maximum extent allowed, subject to exchange/SEC rules."
    },
    "clause12": {
      "continuation": "All obligations continue while Indemnitee is subject to or involved in any proceeding for which indemnification is provided. No action by Company or Affiliate against Indemnitee, spouse, heirs, or representatives for cause of action accrued more than five years (or longer per Swiss law) after accrual is barred and deemed released.",
      "terminationPeriod": "Five years from accrual or longer per Swiss law."
    },
    "clause13": {
      "amendment": "No amendment or waiver effective unless in writing signed by both parties."
    },
    "clause14": {
      "subrogation": "Upon payment, Company is subrogated to Indemnitee’s recovery rights, must execute necessary documents to enforce claims."
    },
    "clause15": {
      "noDuplication": "Company shall not pay for amount already recovered through insurance, Articles, or other indemnity. Liability reduced by amount recovered."
    },
    "clause16": {
      "bindingEffect": "Agreement binds parties and successors by merger, purchase, or other. Successor must assume and perform Agreement in writing with terms acceptable to Indemnitee."
    },
    "clause17": {
      "severability": "If any provision invalid, remaining provisions enforceable to fullest extent. Invalid provision rephrased to preserve intent."
    },
    "clause18": {
      "governingLaw": "New York law applies; indemnification/advancements limited to what Swiss law allows; no provision enforceable if violates Swiss directors’ duties."
    },
    "clause19": {
      "notices": "All notices in writing, by hand, certified/registered mail, addressed to Company at: Chubb Limited, Bärengasse 32, Zurich, Switzerland, and Indemnitee as listed. Effective upon hand delivery or third business day post‑mail. Failure to notify not relieve Company unless materially prejudicial."
    },
    "clause20": {
      "counterparts": "Agreement may be signed in counterparts; all constitute single instrument."
    },
    "execution": {
      "byCompany": "Authorized officer",
      "byIndemnitee": "Authorized signatory or named Indemnitee"
    }
  }
}

