        "section": 4,
        "title": "Death, Long‑Term Disability and Change in Control",
        "clauses": [
          {
            "subsection": "a",
            "description": "For Covered shares where Restricted period not ended, vesting on Date of Termination if death or Long‑Term Disability."
          },
          {
            "subsection": "b",
            "description": "For Covered shares where Restricted period not ended, vesting on Change in Control, provided Change in Control occurs on or before Date of Termination."
          },
          {
            "note": "Special provision regarding Change in Control Date of Termination within 180 days prior to Change in Control: all unvested Covered shares vest on Change in Control date."
          }
        ]
      },
      {
        "section": 5,
        "title": "Restricted Period for Premium Performance Shares",
        "clauses": [
          {
            "description": "Restricted period begins on Grant Date and ends on Vesting Date only if Date of Termination has not occurred before Vesting Date."
          },
          {
            "description": "Vesting determined by multiplying number of Premium shares by Premium Award Performance Percentage."
          },
          {
            "Premium Award Performance Percentage schedule": [
              {"cumulative_performance": "does not meet or exceed 50 %", "percentage": 0},
              {"cumulative_performance": ">= 50 % but < 75 %", "percentage": "linear interpolation between 0 % and 77‑85 %"},
