          },
          {
            "note": "Upon vesting, shares delivered free of restrictions."
          }
        ]
      },
      {
        "section": 6,
        "title": "Transfer and Forfeiture of Shares",
        "clauses": [
          {
            "a",
            "description": "Participant vested in Covered shares when §2 satisfied and Date of Termination not before last day of Restricted period."
          },
          {
            "b",
            "description": "Participant vested in Premium shares when §5 satisfied and Date of Termination not before last day of Restricted period."
          },
          {
            "c",
            "description": "Participant forfeits any Covered or Premium shares as of Date of Termination if termination occurs before Vesting Date, except per §§3, 4, 5."
          },
          {
            "d",
            "description": "Vesting governed solely by terms herein, overriding any employment or severance agreements."
          }
        ]
      },
      {
        "section": 7,
        "title": "Withholding",
        "clauses": [
          {
            "description": "All deliveries, distributions, and vesting subject to applicable tax withholding."
          },
          {
            "option": "Participant may elect withholding via surrender of owned shares or shares entitled under Plan."
          },
          {
            "committee_authority": "Committee may make necessary elections to ensure correct tax withholding."
          }
        ]
      },
      {
        "section": 8,
        "title": "Transferability",
        "clauses": [
          {
            "description": "Awards may not be sold, assigned, transferred, pledged or encumbered prior to vesting and delivery unless otherwise authorized by Committee."
          }
        ]
      },
      {
        "section": 9,
        "title": "Dividends",
        "clauses": [
          {
            "description": "Dividends on Covered and Premium shares paid on record dates after Grant Date and before end of Restricted period are accumulated and distributed on Vesting Date."
          },
          {
            "condition": "No dividends for forfeited shares."
          },
          {
            "457A considerations": {
              "i": "Dividends accumulated by 457A Vesting Date are used to purchase additional shares under same vesting schedule; any cash leftover distributed.",
              "ii": "Dividends paid after 457A Vesting Date and before vesting are used similarly."
            }
          }
        ]
      },
      {
        "section": 10,
        "title": "Voting",
        "clauses": [
          {
            "description": "Participant may vote Covered shares unless forfeited; cannot vote Premium shares before vesting."
          }
        ]
      },
      {
        "section": 11,
        "title": "Deposit of Award",
        "clauses": [
          {
            "description": "Certificates registered in Participant name and deposited in Committee‑designated bank."
          }
        ]
      },
      {
        "section": 12,
        "title": "Definitions (Expanded)",
        "clauses": [
          {
            "label": "Cause",
            "definition": [
              "Conviction of felony or misdemeanor involving moral turpitude;",
              "Willful misconduct or gross negligence causing harm;",
              "Failure to follow board or supervisor directions;",
              "Refusal to cooperate with government authority;",
              "Fraud, embezzlement, theft or dishonesty causing harm;",
              "Material violation of Company policy causing harm."
            ]
          },
          {
            "label": "Change in Control",
            "definition": "As set forth in Plan."
          },
          {
            "label": "Change in Control Date of Termination",
            "definition": "Termination by Company or Subsidiary without Cause (excluding death, Long‑Term Disability, retirement) or by employee for Good Reason occurring between 180 days before and 2 years after a Change in Control."
          },
          {
            "label": "Combined Ratio",
            "definition": "Sum of loss & loss expense ratio, policy acquisition cost ratio, and administrative expense ratio for P&C business; reported in Form 10‑K or average for multi‑year periods."
          },
          {
            "label": "Cumulative Performance",
            "definition": "First Performance Goal × 0.70 + Second Performance Goal × 0.30; example: 80 % × 0.70 + 50 % × 0.30 = 71 %. Calculation and parameters set by Committee."
          },
          {
            "label": "Date of Termination",
            "definition": "Employment termination date for employees; next day after last day of service for directors; excludes transfers; directors may remain if reappointed; leave of absence does not count as termination."
          },
          {
            "label": "Director",
            "definition": "Member of Board, may or may not be employee."
          },
          {
            "label": "First Performance Goal",
            "definition": "Growth in tangible book value per common share (GAAP) for Company vs. Peer Group expressed as percentile rank."
          },
          {
            "label": "Good Reason",
            "definition": [
              "Material reduction in title, authority, duty or responsibility;",
              "Material salary/bonus reduction;",
              "Failure of Company to secure Plan assumption by successor within 45 days after merger or similar transaction."
            ]
          },
          {
            "label": "Long‑Term Disability",
            "definition": "Eligibility under Company's long‑term disability plan (or Committee determination if not participating)."
          },
          {
            "label": "Peer Companies",
            "definition": "Companies in Chubb Financial Performance Peer Group within 90 days of Performance Period start and with financial data available."
          },
          {
            "label": "Performance Period",
            "definition": "Three‑year period from Commencement Date to third anniversary."
          },
          {
            "label": "Retirement",
            "definition": "Termination after ≥10 years service and age ≥ 62, with good standing, release, and program compliance; release conditions tied to Section 409A timing."
          },
          {
            "label": "Second Performance Goal",
            "definition": "Achievement of Combined Ratio vs. Peer Group as percentile rank."
          },
          {
            "label": "Total Shareholder Return",
            "definition": "Total return per share (dividends reinvested) calculated from average of highs and lows over 15 days before performance period start or end; adjustments for splits, recapitalizations, etc."
          }
        ]
      },
      {
        "section": 13,
        "title": "Plan Definitions",
        "clauses": [
          {
            "description": "Terms use words/phrases as in Plan unless context dictates otherwise."
          }
        ]
      },
      {
        "section": 14,
        "title": "Heirs and Successors",
        "clauses": [
          {
            "binding": "Terms binding on Company and successors; delivery after death to Designated Beneficiary (if any), otherwise to estate."
          },
          {
            "designation": "Beneficiary designation in writing filed with Committee."
          }
        ]
      },
      {
        "section": 15,
        "title": "Administration",
        "clauses": [
          {
            "authority": "Committee manages, controls, interprets Terms with binding effect."
          }
        ]
      },
      {
        "section": 16,
        "title": "Plan and Corporate Records Govern",
        "clauses": [
          {
            "priority": "Corporate records control over discrepancies with Record‑Keeping System."
          },
          {
            "reference": "Terms subject to Plan, Committee amendments; interpretive authority rests with Committee."
          }
        ]
      },
      {
        "section": 17,
        "title": "Clawback Policy",
        "clauses": [
          {
            "description": "Rights under this award subject to Chubb Limited Clawback Policy (amended as time to time)."
          }
        ]
      },
      {
        "section": 18,
        "title": "Solicitation Activity (Non‑Solicit Period)",
        "clauses": [
          {
            "scope": "During employment and one year after termination; prohibits solicitation of customers/customers, hiring of Employees, breach of confidentiality."
          },
          {
            "substance": [
              "No solicitation of business or customer within one year of termination if communications occurred and/or confidential info accessed.",
              "No solicitation of employees.",
              "No breach of confidentiality, non‑solicitation or non‑competition agreements."
            ]
          },
          {
            "acknowledgment": "Provisions not more restrictive, reasonably limited, not harmful, not burdensome."
          },
          {
            "relief": "Company may seek injunctive relief without bond; remedies in addition to other legal remedies."
          },
          {
            "tolling": "Non‑Solicit Period tolled during any violation of this paragraph."
          }
        ]
      },
      {
        "section": 19,
        "title": "Not an Employment Contract",
        "clauses": [
          {
            "description": "Award does not confer right to continued employment or interfere with Company’s right to terminate or modify employment."
          }
        ]
      },
      {
        "section": 20,
        "title": "Notices",
        "clauses": [
          {
            "delivery_methods": [
              "hand delivered",
              "fax",
              "overnight courier",
              "first‑class mail (received after 3 business days or actual receipt)."
            ],
            "addresses": {
              "to_participant": "Participant’s address in Company records",
              "to_company": "Company principal executive office"
            }
          }
        ]
      },
      {
        "section": 21,
        "title": "Fractional Shares",
        "clauses": [
          {
            "description": "Instead of issuing fraction, Company may pay fair market value of fractional share."
          }
        ]
      },
      {
        "section": 22,
        "title": "Amendment",
        "clauses": [
          {
            "authority": "Terms may be amended per Plan or by written agreement of Participant and Company without other consent."
          }
        ]
      }
    ]
  },
  "signature": {
    "appearance_date": "Grant Date",
    "issuer": "Chubb Limited",
    "representative": "Its: 10"
  }
}

